sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    try {
        var encryptedMsgId = current.encrypted_message_id;
        var taskId = current.servicenow_task_id;
        var caseId = current.servicenow_task_id.parent;
        var eLog = new GlideRecord("x_hsb11_mss_smh_hsbc_symphony_message_log");
        eLog.addQuery("servicenow_task_id", taskId);
        eLog.addQuery("encrypted_message_id", '=', null);
        eLog.addQuery("state", '=', 'Draft');
        eLog.addQuery("type", current.type);
        eLog.query();
        if (eLog.next()) {
            eLog.encrypted_message_id = encryptedMsgId;
            eLog.response_body = current.response_body;
            eLog.response_code = current.response_code;
            eLog.response_date = current.response_date;
            eLog.state = current.state;
            eLog.update();
        }
        var taskState = 1;
        if (current.state == "Processed") {
            taskState = 3;
        } else if (current.state == "Error") {
            taskState = 7;
        }
        var parent = new GlideRecord("x_hsb11_mss_smh_parent_aggregated_trade_chat_queue");
        parent.addQuery("trade_task_reference.parent", caseId);
        parent.query();
        if (parent.next()) {
            parent.encryptedmessageid = encryptedMsgId;
            parent.aggregation_status = 'Sent';
            parent.update();

            if (parent.trade_count > 1) {
                var parentnumber = parent.getDisplayValue('number');
                var child = new GlideRecord("x_hsb11_mss_smh_child_aggregated_trade_chat_queue");
                child.addQuery("parent.number", parentnumber);
                child.query();
                while (child.next()) {
                    updateTradeTask(child.trade_case_task.sys_id, taskState);
                }
            } else {
                updateTradeTask(taskId.sys_id, taskState);
            }

            // if children are all actioned, mark SLA task as cancelled. 
            var tradeCases = [];
			var newTradeCase = '';
            var isAllActioned = true;
            var children = new GlideRecord("x_hsb11_mss_smh_child_aggregated_trade_chat_queue");
            children.addQuery('parent', parent.sys_id);
            children.query();

            while (children.next()) {
                if (children.actioned == false) {
					newTradeCase = children.getValue('trade_case');
                    isAllActioned = false;
                    break;
                } else {
                    tradeCases.push(children.getValue('trade_case')); // get trade case list from child
                }
            }
            var slaTask = new GlideRecord('x_hsb11_hsbc_mss_t_trade_task');
            slaTask.addQuery('parent', 'IN', tradeCases);
            slaTask.addQuery('short_description', 'SLA for client responding to symphony message has been exceeded - User to follow up and determine next steps and close the existing task');
            slaTask.query();
            if (slaTask.next()) { // if SLA task exists
                if (isAllActioned) { // if children are all actioned
                    slaTask.state = 7; // update state to cancel
                    slaTask.update();
                }else { // if children NOT all actioned
					if(slaTask.hsbc_trade_case != newTradeCase){ 
						slaTask.hsbc_trade_case = newTradeCase;
						slaTask.parent = newTradeCase;
						slaTask.parent_case = newTradeCase;
						slaTask.update();
					}
				}
            }

        } else {
            updateTradeTask(taskId.sys_id, encryptedMsgId, taskState);
            // tradeTask = new GlideRecord("x_hsb11_hsbc_mss_t_trade_task");
            // tradeTask.addQuery("number", taskId.number);
            // tradeTask.query();
            // if (tradeTask.next()) {
            //     tradeTask.encryptedmessageid = encryptedMsgId;
            //     tradeTask.state = taskState;
            //     tradeTask.update();
            // }
        }
        if (current.state == "Error") {
            var failureDescription = "Cash Equities Symphony Outbound message processing Widget failure, details of the error are as below - ServiceNow Reference -" + current.servicenow_task_id.number + " Timestamp : " + current.response_date + "Error code - " + current.response_code + "Error Body - " + current.error_body; //MSSOTIQUBE-1358
            var createEventForWidgetFailure = new x_hsb11_hsbc_mss_t.hsbcWidgetFailureHandler().createITIDEvent('WARNING', failureDescription, 'MSSiQubeSNWidget_Symphony');
        }
    } catch (e) {
        gs.error('[BR][mss.symphony_process_message_response]: ' + e.getMessage());
    }

    function updateTradeTask(taskId, taskState) {
        var tradeTask = new GlideRecord("x_hsb11_hsbc_mss_t_trade_task");
        tradeTask.addQuery('sys_id', taskId);
        tradeTask.query();
        if (tradeTask.next()) {
            tradeTask.state = taskState;
            tradeTask.update();
        }
    }
})(current, previous);
